class ListNode:
    def __init__(self, val: int = 0, next: "ListNode | None" = None):
        self.val = val
        self.next = next


def loop_entrance(head: ListNode | None) -> ListNode | None:
    # The first stop reached a second time is where the loop starts. Remember
    # stops by identity: values repeat, so a value can't name a stop.
    seen = set()
    while head is not None:
        if id(head) in seen:
            return head
        seen.add(id(head))
        head = head.next
    return None

