use std::cell::RefCell;
use std::rc::Rc;
use std::collections::HashSet;

fn loop_entrance(head: Option<Rc<RefCell<CyclicListNode>>>) -> Option<Rc<RefCell<CyclicListNode>>> {
    // The first stop reached a second time is where the loop starts. Remember
    // stops by address (Rc::as_ptr): values repeat, so a value can't name a stop.
    let mut seen = HashSet::new();
    let mut cur = head;
    while let Some(node) = cur {
        if !seen.insert(Rc::as_ptr(&node)) {
            return Some(node);
        }
        cur = node.borrow().next.clone();
    }
    None
}

