class ListNode:
    def __init__(self, val: int = 0, next: "ListNode | None" = None):
        self.val = val
        self.next = next


def loop_entrance(head: ListNode | None) -> ListNode | None:
    # 1. Two walkers, one twice as fast. If the route ends, there's no loop;
    #    otherwise the fast one laps the slow one somewhere inside the loop.
    slow = fast = head
    while True:
        if fast is None or fast.next is None:
            return None
        slow, fast = slow.next, fast.next.next
        if slow is fast:
            break
    # 2. From the meeting point and from the start, walk in step: they meet
    #    exactly at the entrance.
    a, b = head, slow
    while a is not b:
        a, b = a.next, b.next
    return a

