use std::cell::RefCell;
use std::rc::Rc;

type Link = Option<Rc<RefCell<CyclicListNode>>>;

fn step(link: &Link) -> Link {
    link.as_ref().and_then(|node| node.borrow().next.clone())
}

fn same(a: &Link, b: &Link) -> bool {
    matches!((a, b), (Some(x), Some(y)) if Rc::ptr_eq(x, y))
}

fn loop_entrance(head: Option<Rc<RefCell<CyclicListNode>>>) -> Option<Rc<RefCell<CyclicListNode>>> {
    // 1. Two walkers, one twice as fast. If the route ends, there's no loop;
    //    otherwise the fast one laps the slow one somewhere inside the loop.
    let (mut slow, mut fast) = (head.clone(), head.clone());
    loop {
        fast = step(&step(&fast));
        if fast.is_none() {
            return None;
        }
        slow = step(&slow);
        if same(&slow, &fast) {
            break;
        }
    }
    // 2. From the meeting point and from the start, walk in step: they meet
    //    exactly at the entrance.
    let mut a = head;
    while !same(&a, &slow) {
        a = step(&a);
        slow = step(&slow);
    }
    a
}
